 28	/**
 29	 * Resolve which project name to use.
 30	 * Precedence: valid query > valid stored > valid default > first listed.
 31	 * If query names a project that is not listed, surface invalidQueryProject and fall back.
 32	 */
 33	export function ResolveProjectSelection(
 34	  queryProject,
 35	  storedProject,
 36	  defaultProject,
 37	  listedProjects
 38	) {
 39	  const valid = new Set(listedProjects);
 40	  const isValid = (p) => p != null && String(p).length > 0 && valid.has(String(p));
 41	
 42	  let invalidQueryProject = null;
 43	  if (queryProject != null && String(queryProject).length > 0 && !isValid(queryProject)) {
 44	    invalidQueryProject = String(queryProject);
 45	  }
 46	
 47	  if (isValid(queryProject)) {
 48	    return { project: String(queryProject), invalidQueryProject: null };
 49	  }
 50	  if (isValid(storedProject)) {
 51	    return { project: String(storedProject), invalidQueryProject };
 52	  }
 53	  if (isValid(defaultProject)) {
 54	    return { project: String(defaultProject), invalidQueryProject };
 55	  }
 56	  const first = listedProjects.length ? listedProjects[0] : null;
 57	  return { project: first, invalidQueryProject };
 58	}
