165	export class RefreshScheduler {
166	  constructor(options) {
167	    this.m_intervalMs = options.intervalMs;
168	    this.m_onTick = options.onTick;
169	    this.m_getVisible = options.getVisible;
170	    this.m_timer = null;
171	    this.m_onVisibility = () => {
172	      if (this.m_getVisible()) {
173	        void this.m_onTick();
174	      }
175	    };
176	  }
177	
178	  Start() {
179	    this.Stop();
180	    this.m_timer = setInterval(() => {
181	      if (this.m_getVisible()) {
182	        void this.m_onTick();
183	      }
184	    }, this.m_intervalMs);
185	    if (typeof document !== "undefined") {
186	      document.addEventListener("visibilitychange", this.m_onVisibility);
187	    }
188	  }
189	
190	  Stop() {
191	    if (this.m_timer != null) {
192	      clearInterval(this.m_timer);
193	      this.m_timer = null;
194	    }
195	    if (typeof document !== "undefined") {
196	      document.removeEventListener("visibilitychange", this.m_onVisibility);
197	    }
198	  }
199	}
