201	export function MergeRunBadge(overview, runStatus) {
202	  const overlay = overview?.execution_overlay_status ?? "none";
203	  const activeRun = runStatus?.active_run;
204	  if (overlay === "human_intervention") {
205	    return { label: "Human intervention required", variant: "hi" };
206	  }
207	  if (overlay === "paused") {
208	    const until = overview?.paused_until ?? runStatus?.paused_until;
209	    return {
210	      label: until ? `Paused until ${until}` : "Paused",
211	      variant: "paused",
212	    };
213	  }
214	  if (overlay === "running" || activeRun != null) {
215	    return { label: "Running", variant: "running" };
216	  }
217	  return { label: "Idle / Not running", variant: "idle" };
218	}

